  "Could not save store settings. Try again.": {
    "fr": "Impossible d’enregistrer les réglages. Réessayez.",
    "ar": "تعذر حفظ إعدادات المتجر. حاول مجددًا.",
    "es": "Impossibel d’Guardar las réglages. Réessayez."
  },
  "Choose Personal Store for your own catalog, product pages, cart and seven configurable payment methods. Choose Affiliate Deals Shop for partner deals and external checkout. Free includes both primary multi-category stores; Pro adds up to 10 independent niche shops across both types. Inventories and settings stay separate.": {
    "fr": "Choisissez une boutique personnelle pour vos produits, panier et sept paiements, ou une boutique affiliée pour les offres partenaires. L’offre gratuite inclut les deux boutiques principales multirubriques ; Pro ajoute jusqu’à 10 boutiques spécialisées indépendantes, tous types confondus. Catalogues et réglages restent séparés.",
    "ar": "اختر متجرًا شخصيًا لمنتجاتك وسلة التسوق وسبع طرق دفع، أو متجر عروض بالعمولة لروابط الشركاء. تشمل الخطة المجانية المتجرين الأساسيين متعددي الفئات، وتضيف Pro حتى 10 متاجر متخصصة مستقلة عبر كلا النوعين. تبقى الكتالوجات والإعدادات منفصلة.",
    "es": "Choisissez una Tienda personnelel pour vos Productos, panier y sept Pagos, ou una Tienda affiliée pour las offres partenaires. L’offre Gratise inclut las deux Tiendas principalas multirubriques ; Pro ajoute jusqu’à 10 Tiendas spécialisées indépendantes, tous types confondus. Catalogues y réglages restent séparés."
  },
  "The post formatter, browser media tools and two primary stores are free. An active Pro license adds up to 10 specialty niche shops and the seller dashboard. External payment providers or networks may charge their own fees. Share each store anywhere: TikTok and Instagram bios, Pinterest, Facebook, YouTube, WhatsApp, blogs or search listings.": {
    "fr": "L’outil de publications, le studio média et les deux boutiques principales sont gratuits. Pro ajoute jusqu’à 10 boutiques spécialisées et le tableau vendeur. Les prestataires de paiement et réseaux peuvent facturer leurs frais. Partagez chaque boutique sur TikTok, Instagram, Pinterest, Facebook, YouTube, WhatsApp, blogs ou moteurs de recherche.",
    "ar": "أداة المنشورات واستوديو الوسائط والمتجران الأساسيان مجانية. تضيف Pro حتى 10 متاجر متخصصة ولوحة تحكم البائع. قد تفرض جهات الدفع أو الشبكات رسومها الخاصة. شارك كل متجر عبر TikTok وInstagram وPinterest وFacebook وYouTube وWhatsApp والمدونات أو نتائج البحث.",
    "es": "L’outil de publications, el studio média y las deux Tiendas principalas sont Gratiss. Pro ajoute jusqu’à 10 Tiendas spécialisées y el tabelau Vendedor. las prestataires de Pago y réseaux peuvent facturer elurs frais. Partagez chaque Tienda sur TikTok, Instagram, Pinterest, Facebook, YouTube, WhatsApp, blogs ou moteurs de recherche."
  },
