  "How SellPostly Works": {
    "fr": "Comment fonctionne SellPostly",
    "ar": "كيف يعمل SellPostly",
    "es": "Comment fonctionne SellPostly"
  },
  "SellPostly is strictly a SaaS storefront software provider. Independent shops do not represent the SellPostly brand. Products, fulfillment, payments and direct transactions are solely between the buyer and the independent seller.": {
    "fr": "SellPostly fournit uniquement un logiciel de boutique en mode SaaS. Les boutiques indépendantes ne représentent pas la marque SellPostly. Les produits, la livraison, les paiements et les transactions directes relèvent exclusivement de l’acheteur et du vendeur indépendant.",
    "ar": "SellPostly مزوّد برمجيات متاجر بنظام SaaS فقط. لا تمثّل المتاجر المستقلة علامة SellPostly. المنتجات والتنفيذ والمدفوعات والمعاملات المباشرة تتم حصرًا بين المشتري والبائع المستقل.",
    "es": "SellPostly fournit uniquement un logiciel de Tienda en mode SaaS. las Tiendas indépendantes ne représentent pas la marque SellPostly. las Productos, la Entrega, las Pagos y las transactions directes relèvent exclusivement de l’Comprador y du Vendedor indépendant."
  },
